// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCollection, createCollectionMember, deleteCollectionMember, getCollectionMembers, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // The collection is owned by the caller, so every refusal below is about the input
    // rather than about the endpoint's ownership check.
    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, "tb-members-rejections");
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("tb-members-rejections");
    const collectionId = getResponseValue(collectionsPostResponse, "response.id");
    expect(collectionId, 'id').toBeGreaterThan(0);

    // An invite that names no email is refused.
    const collectionsMembersPostRequestBody: string = `{
        "role": "viewer"
    }`;
    const collectionsMembersPostResponse = await createCollectionMember(client, URL_localhost, headers, collectionId, collectionsMembersPostRequestBody, 400);
    expect(getResponseValue(collectionsMembersPostResponse, "response"), 'response').toBe("email is required.");

    // An invite for an email that belongs to no user is refused.
    const collectionsMembersPost1RequestBody: string = `{
        "email": "tb-unknown-invitee@example.com"
    }`;
    const collectionsMembersPost1Response = await createCollectionMember(client, URL_localhost, headers, collectionId, collectionsMembersPost1RequestBody, 404);
    expect(collectionsMembersPost1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(collectionsMembersPost1Response, "response"), 'response').toBe("User not found.");

    // A removal that names no member is refused.
    const collectionsMembersDeleteResponse = await deleteCollectionMember(client, URL_localhost, headers, collectionId, {}, 400);
    expect(collectionsMembersDeleteResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(collectionsMembersDeleteResponse, "response"), 'response').toBe("userId query param is required.");

    // A collection id that exists for no collection is refused.
    const membersGetResponse = await getCollectionMembers(client, URL_localhost, headers, 999999999, 404);
    expect(getResponseValue(membersGetResponse, "response"), 'response').toBe("Collection not found.");

    // A non-numeric collection id is refused before any lookup happens.
    const abcMembersGetResponse = await getCollectionMembers(client, URL_localhost, headers, "abc", 400);
    expect(abcMembersGetResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcMembersGetResponse, "response"), 'response').toBe("Invalid collection ID.");

    // None of the refusals added a member.
    const membersGet1Response = await getCollectionMembers(client, URL_localhost, headers, collectionId);
    expect(getResponseValue(membersGet1Response, "response").length, 'the refused invites added no member').toBe(0);
    expect(getResponseValue(membersGet1Response, "response.0"), 'response.0').toBeNull();

    await deleteCollection(client, URL_localhost, headers, collectionId);
});
